/* @lc app=leetcode id=3404 lang=kotlin */ class Solution { fun g(a: Int, b: Int): Int = if (b == 0) a else g(b, a % b) fun key(a: Int, b: Int): Long = g(a, b).let { d -> (a / d).toLong() * 1_000_003 + b / d } fun numberOfSubsequences(nums: IntArray): Long = HashMap<Long, Int>().let { m -> (4..nums.size - 3).fold(0L) { acc, r -> (0..r - 4).forEach { p -> m.merge(key(nums[p], nums[r - 2]), 1) { a, b -> a + b } }.let { acc + (r + 2 until nums.size).sumOf { s -> (m[key(nums[s], nums[r])] ?: 0).toLong() } } } } }